mapper.select:
SELECT wti.id AS instanceId, wti.source_type AS sourceType, wti.source_id AS sourceId, wti.source_code AS sourceCode, wti.status AS status, wti.current_index AS currentIndex, wti.total_steps AS totalSteps, CASE WHEN wti.total_steps IS NULL OR wti.total_steps = 0 THEN 0 ELSE LEAST(100, FLOOR( (SELECT COUNT(1) FROM workflow_task_record wtr WHERE wtr.instance_id = wti.id AND wtr.is_deleted = false AND wtr.status = 'success') * 100.0 / wti.total_steps)) END AS progressPercent, db.name AS currentNodeName, wti.last_error AS lastError, wtr_cur.retry_count AS retryCount, wti.trace_id AS traceId, wti.create_time AS createTime, wti.update_time AS updateTime, wti.create_user_name AS createUserName FROM workflow_task_instance wti LEFT JOIN workflow_task_record wtr_cur ON wtr_cur.instance_id = wti.id AND wtr_cur.index = wti.current_index AND wtr_cur.is_deleted = false LEFT JOIN dict_basic db ON db.id = wtr_cur.dict_basic_id AND db.is_deleted = false
${params.sqlMap.default}
${params.permissionSql}
AND wti.is_deleted = false
AND wti.source_type IN
#{item}
AND wti.status IN
#{item}
AND wti.source_code ILIKE CONCAT('%', #{params.sourceCode}, '%')
AND wti.source_id = #{params.sourceId}
AND wti.status IN ('failed', 'waiting')
AND db.name ILIKE CONCAT('%', #{params.currentNodeName}, '%')
AND EXISTS ( SELECT 1 FROM workflow_task_record wtrf WHERE wtrf.instance_id = wti.id AND wtrf.is_deleted = false AND wtrf.target_service = #{params.targetService} )
ORDER BY
${item.field} ${item.sort}
wti.update_time DESC

SELECT wti.id AS instanceId, wti.source_type AS sourceType, wti.source_id AS sourceId, wti.source_code AS sourceCode, wti.status AS status, wti.current_index AS currentIndex, wti.total_steps AS totalSteps, wti.last_error AS lastError, wti.trace_id AS traceId, wti.create_time AS createTime, wti.update_time AS updateTime, wti.create_user_name AS createUserName, wti.start_time AS startTime, wti.finish_time AS finishTime FROM workflow_task_instance wti WHERE wti.is_deleted = false AND wti.id IN
#{id}
ORDER BY wti.create_time DESC

SELECT wtr.instance_id AS instanceId, wtr.id AS stepId, wtr.index AS index, db.name AS nodeName, wtr.class_path AS classPath, wtr.target_service AS targetService, wtr.target_endpoint AS targetEndpoint, wtr.feign_duration_ms AS feignDurationMs, wtr.error_source AS errorSource, wtr.status AS status, wtr.retry_count AS retryCount, wtr.last_error AS lastError, wtr.input_data AS inputData, wtr.output_data AS outputData, wtr.start_time AS startTime, wtr.end_time AS endTime, CASE WHEN wtr.start_time IS NOT NULL AND wtr.end_time IS NOT NULL THEN EXTRACT(EPOCH FROM (wtr.end_time - wtr.start_time)) * 1000 ELSE NULL END AS durationMs, wtr.remark AS remark FROM workflow_task_record wtr LEFT JOIN dict_basic db ON db.id = wtr.dict_basic_id AND db.is_deleted = false WHERE wtr.is_deleted = false AND wtr.instance_id IN
#{id}
ORDER BY wtr.instance_id ASC, wtr.index ASC

SELECT wti.id
FROM workflow_task_instance wti
WHERE wti.is_deleted = false
  AND wti.source_type = #{params.sourceType}
  AND wti.source_id = #{params.sourceId}

    ${params.permissionSql}

ORDER BY wti.create_time DESC

SELECT wtr.source_type AS sourceType, wtr.dict_basic_id AS dictBasicId, db.name AS dictBasicName, wtr.target_service AS targetService, SUM(CASE WHEN wtr.status = 'failed' THEN 1 ELSE 0 END) AS failedCount, SUM(CASE WHEN wtr.status = 'waiting' THEN 1 ELSE 0 END) AS waitingCount, COALESCE(AVG(wtr.retry_count), 0)::INT AS avgRetryCount, MAX(wtr.update_time) AS lastOccurTime FROM workflow_task_record wtr INNER JOIN workflow_task_instance wti ON wti.id = wtr.instance_id AND wti.is_deleted = false LEFT JOIN dict_basic db ON db.id = wtr.dict_basic_id AND db.is_deleted = false WHERE wtr.is_deleted = false AND wtr.status IN ('failed', 'waiting')
${params.permissionSql}
AND wtr.source_type IN
#{item}
AND wtr.target_service = #{params.targetService}
GROUP BY wtr.source_type, wtr.dict_basic_id, db.name, wtr.target_service ORDER BY failedCount DESC, lastOccurTime DESC
